let cronRun = null;
try {
  cronRun = $('Code: Set Cron Run Context').first().json;
} catch (error) {}

const runSource = cronRun?.runSource === 'cron' ? 'cron' : 'manual';
const runSlot = runSource === 'cron' ? cronRun.runSlot : null;
const today = runSource === 'cron'
  ? cronRun.today
  : DateTime.now().setZone('Asia/Makassar').toISODate();

let _cc = {};
try { _cc = $('Load Master Context').first().json; } catch(e) {}
let _editorial = _cc.editorial_scope || {};

let form = {};
try {
  const formItems = $('Form Trigger - Manual Run').all();
  if (formItems.length > 0) form = formItems[0].json || {};
} catch(e) { form = {}; }

let planRows = [];
try { planRows = $('Load Plan from Sheets').all().map(i => i.json); } catch (error) {}
let historyRows = [];
try { historyRows = $('Load Content History').all().map(i => i.json); } catch (error) {}
const parseArr = (str) => typeof str === 'string' ? str.split(',').map(s => s.trim()).filter(Boolean) : (Array.isArray(str) ? str : []);

const account_context = (form.account_context || '').trim();
let form_context = null;

if (account_context) {
  try {
    form_context = JSON.parse(account_context);
  } catch(e) {
    const parsed = {};
    account_context.split('\n').forEach(line => {
      const m = line.match(/^([\w][\w\s]*?)\s*[:\-]\s*(.+)$/);
      if (m) parsed[m[1].trim().toLowerCase().replace(/\s+/g,'_')] = m[2].trim();
    });
    form_context = {
      batch_id: parsed.batch_id || 'batch_001',
      account_handle: parsed.handle || parsed.account_handle || '',
      niche: parsed.niche || account_context.substring(0, 100),
      target_audience: parsed.audience || parsed.target_audience || 'tech enthusiasts',
      target_description: parsed.description || parsed.target_description || account_context,
      sub_topics: parsed.sub_topics || parsed.topics || 'AI tools,Python,automation,LLM,productivity',
      forbidden_topics: parsed.forbidden_topics || parsed.forbidden || '',
      formats: parsed.formats || 'carousel',
      tone: parsed.tone || 'educational,casual,data-driven',
      language: parsed.language || 'EN',
      forbidden_phrases: parsed.forbidden_phrases || 'game changer,revolutionary,unleash',
      research_focus: parsed.research || parsed.research_focus || 'data-backed insights, real tools, 2025-2026 only',
      anti_generic_notes: parsed.anti_generic_notes || 'avoid vague claims, need specific stats or tool names',
      allowed_templates: parsed.templates || parsed.allowed_templates || 'DAHMOhYIffY',
      total_days: parsed.total_days || '7',
      notify_time: parsed.notify_time || '07:00',
      start_date: parsed.start_date || new Date().toISOString().split('T')[0],
    };
  }
}

const mc = form_context || {};
const rawWatermarkHandle = String(form.watermark_handle || mc.account_handle || '').trim();
const normalizedWatermarkHandle = rawWatermarkHandle.replace(/^@+/, '').trim();
const accountWatermark = normalizedWatermarkHandle ? '@' + normalizedWatermarkHandle : '';
const followCta = accountWatermark ? 'Follow ' + accountWatermark + ' for more.' : 'Follow my account';
const guardAudience = String($json.guard_audience || '').trim();
const language_override = (form.language && form.language !== 'Auto') ? form.language : '';

const masterContext = {
  batch_id: mc.batch_id || 'batch_001',
  account: { username: normalizedWatermarkHandle, handle: accountWatermark, niche: mc.niche || (_editorial.audience ? _editorial.audience : 'Tech & AI') },
  audience: { target: guardAudience || mc.target_audience || 'a general audience', description: mc.target_description || guardAudience || (_editorial.audience || '') },
  scope: { sub_topics: parseArr(mc.sub_topics).length > 0 ? parseArr(mc.sub_topics) : ['facts','examples','trade-offs','common mistakes'], forbidden_topics: parseArr(mc.forbidden_topics), formats: parseArr(mc.formats) },
  voice: { tone: parseArr(mc.tone).length > 0 ? parseArr(mc.tone) : ['clear','practical','accessible'], language: language_override || mc.language || 'EN', forbidden_phrases: parseArr(mc.forbidden_phrases) },
  research: { focus: mc.research_focus || 'primary sources, evidence, real examples', anti_generic_notes: mc.anti_generic_notes || 'avoid vague claims, need specific facts or practical outcomes', year_min: 2025 },
  output: { allowed_templates: parseArr(mc.allowed_templates), total_days: parseInt(mc.total_days) || 7, notify_time: mc.notify_time || '07:00', start_date: mc.start_date || '' },
};

const topic_override = (form.topic_override || '').trim();
const topic_detail = (form.topic_detail || '').trim();
const keywords_raw = (form.keywords || '').trim();
const parsedSubtopics = [];
let parsedKeywords = keywords_raw
  ? keywords_raw.split(',').map(s => s.trim()).filter(Boolean)
  : [];
let researchSources = [];

const normalizeSlot = (value) => Number.parseInt(String(value), 10);
const validTemplates = new Set(['tips-content', 'code-content', 'visual-content', 'template1-content', 'insight-content', 'editorial-content', 'momentum-content']);

let status;
let activePlan = null;
let planClaim = null;
let mpId = null;
let runOptions = {};

function slugify(value) {
  return String(value || 'general').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+/g, '-').replace(/^-+|-+$/g, '') || 'general';
}

function buildMpId(date, slotPart, topic) {
  const todayStr = String(date || new Date().toISOString().slice(0, 10)).replace(/[^0-9]/g, '').slice(0, 8);
  let mpId = 'mp-' + todayStr + '-' + slotPart + '-' + slugify(topic);
  if (mpId.length > 96) {
    let hash = 0;
    for (let i = 0; i < mpId.length; i++) hash = (hash * 31 + mpId.charCodeAt(i)) >>> 0;
    mpId = mpId.slice(0, 87) + '-' + hash.toString(36).slice(0, 8);
  }
  return mpId;
}

if (runSource === 'cron') {
  const matchingPlans = planRows.filter((row) =>
    row.date === today &&
    normalizeSlot(row.slot) === runSlot &&
    row.status === 'pending' &&
    row.plan_id &&
    row.topic &&
    validTemplates.has(row.template)
  );

  if (matchingPlans.length > 1) {
    console.warn(`Duplicate content plan slot: ${today} slot ${runSlot} has ${matchingPlans.length} pending rows; using the first.`);
  }

  const scheduledPlan = matchingPlans[0];

  if (!scheduledPlan) {
    return [{ json: { runSource, runSlot, status: 'NO_PLAN', today, masterContext, content_context: _cc, editorial_scope: _editorial } }];
  }

  activePlan = { ...scheduledPlan };
  parsedKeywords = parseArr(scheduledPlan.keywords);
  try {
    researchSources = typeof scheduledPlan.sources === 'string'
      ? JSON.parse(scheduledPlan.sources || '[]')
      : (Array.isArray(scheduledPlan.sources) ? scheduledPlan.sources : []);
  } catch (error) {
    researchSources = [];
  }
  const slotPart = 's' + runSlot;
  mpId = buildMpId(today, slotPart, scheduledPlan.topic);
  planClaim = { plan_id: scheduledPlan.plan_id, mpId, date: today, slot: runSlot, duplicateSlotCount: matchingPlans.length };
  status = 'HAS_PLAN';

  runOptions = {
    template: scheduledPlan.template || 'tips-content',
    research_lens: scheduledPlan.research_lens || '',
    content_mode: 'Auto',
    slide_count: 'Auto',
    image_handling: 'Auto',
    image_url: '',
    test_mode: 'Live run',
    account_watermark: accountWatermark,
    follow_cta: followCta,
  };
} else {
  if (!topic_override) {
    return [{ json: { runSource, status: 'NO_MANUAL_TOPIC', today, masterContext, content_context: _cc, editorial_scope: _editorial } }];
  }

  activePlan = { date: today, topic: topic_override, angle: '', format: 'carousel', status: 'pending', research_lens: '' };
  mpId = buildMpId(today, 'manual', topic_override);
  planClaim = null;
  status = 'HAS_PLAN';

  runOptions = {
    template: (form.template && form.template !== 'Auto') ? form.template : '',
    research_lens: (form.research_lens && form.research_lens !== 'Auto') ? form.research_lens : '',
    content_mode: (form.content_mode && form.content_mode !== 'Auto') ? form.content_mode : 'Auto',
    slide_count: form.slide_count || 'Auto',
    image_handling: form.image_handling || 'Auto',
    image_url: (form.image_url || '').trim(),
    test_mode: form.test_mode || 'Live run',
    account_watermark: accountWatermark,
    follow_cta: followCta,
    email: (form.email || '').trim(),
    language: language_override,
  };
}

const recent = historyRows.filter(r => r.status === 'success').slice(-7).map(r => ({
  date: r.date || '', topic: r.chosen_topic || '', angle: r.angle || '',
  key_stat: r.key_stat || '', headline: r.headline || '', content_type: r.content_type || ''
}));

const LENSES = ['Deep dive / focused analysis','Statistics & surprising numbers','Case study / real example','Common mistakes people make','Contrast: what people think vs reality','Latest data & trends this year','Direct comparison (A vs B)','Actionable data-based tips'];
const dayOfYear = Math.floor((new Date(today) - new Date(new Date(today).getFullYear(), 0, 0)) / 86400000);
const research_lens_override = (form.research_lens && form.research_lens !== 'Auto') ? form.research_lens : null;
const todayLens = research_lens_override || activePlan.research_lens || LENSES[dayOfYear % LENSES.length];

const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const weekdays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const dObj = new Date(today + 'T12:00:00');
const dateDisplay = weekdays[dObj.getDay()] + ', ' + months[dObj.getMonth()] + ' ' + dObj.getDate() + ', ' + dObj.getFullYear();

const research_constraints = (form.research_constraints || '').trim();
const content_mode_override = (form.content_mode && form.content_mode !== 'Auto') ? form.content_mode : null;
const slide_count_pref = form.slide_count || 'Auto';
const image_handling = form.image_handling || 'Auto';
const image_url = (form.image_url || '').trim();
const test_mode = form.test_mode || 'Live run';

const image_source = image_url ? 'user_url' : 'none';

return [{ json: {
  activePlan, masterContext, recent_content: recent, todayLens, today, dateDisplay,
  _retry_count: 0, research_constraints, content_mode_override,
  slide_count_pref, image_handling, image_url, image_source, test_mode,
  topic_detail, parsedSubtopics, parsedKeywords, researchSources,
  account_watermark: accountWatermark, follow_cta: followCta,
  content_context: _cc, editorial_scope: _editorial,
  runSource, runSlot, status, mpId, planClaim, runOptions,
} }];

const text = ($input.first().json.message?.text || '').trim().toLowerCase();
const brief = $('Parse Brief').first().json;

let action = 'proceed';
let extra_context = null;
let image_url = brief.image_url || null;
let new_topic = null;

if (text === 'skip') {
  action = 'skip';
} else if (text.startsWith('ganti:')) {
  action = 'proceed';
  new_topic = text.replace('ganti:', '').trim();
} else if (text.startsWith('tambah:')) {
  action = 'proceed';
  extra_context = text.replace('tambah:', '').trim();
} else if (text.startsWith('img:')) {
  action = 'proceed';
  image_url = text.replace('img:', '').trim();
}

// Determine image_source: Telegram img: overrides form setting
const image_handling = brief.image_handling || 'Auto';
let image_source;
if (image_url && text.startsWith('img:')) {
  image_source = 'user_url';
} else if (image_handling === 'Generate with AI' || (image_handling === 'Auto' && brief.image_needed)) {
  image_source = 'ai_generate';
} else if (image_handling === 'Use custom URL' && image_url) {
  image_source = 'user_url';
} else {
  image_source = 'none';
}

return [{
  json: {
    ...brief,
    action,
    extra_context,
    image_url,
    image_source,
    new_topic: new_topic || brief.activePlan?.topic,
    should_skip: action === 'skip',
  }
}];

// Validate render log from Code: Read Render Log
const renderLog = $input.first().json;
const errors = [];

if (!renderLog.mpId) errors.push('missing mpId');
if (renderLog.totalSlides !== 7) errors.push('expected 7 slides, got ' + renderLog.totalSlides);
if (renderLog.successfulSlides !== renderLog.totalSlides) errors.push('successfulSlides (' + renderLog.successfulSlides + ') !== totalSlides (' + renderLog.totalSlides + ')');
if (!Array.isArray(renderLog.pngPaths) || renderLog.pngPaths.length !== 7) errors.push('expected 7 PNG paths, got ' + (renderLog.pngPaths ? renderLog.pngPaths.length : 0));
if (Number(renderLog.failedSlides || 0) > 0) errors.push(renderLog.failedSlides + ' slide(s) failed to render');

if (errors.length > 0) {
  return [{ json: { status: 'INVALID', errors, ...renderLog } }];
}
return [{ json: { status: 'OK', errors: [], ...renderLog } }];

const upstream = $input.first().json || {};
const fs = require('fs');
const path = '/home/node/ig-templates-demo/content-context.json';
const contentContext = JSON.parse(fs.readFileSync(path, 'utf8'));
const editorialScope = contentContext.editorial_scope || {};

return [{
  json: {
    ...upstream,
    content_context: contentContext,
    editorial_scope: editorialScope,
    context_loaded: true,
    context_source: 'content-context.json',
  },
}];

const input = $input.first().json;
let previousRetryCount = input._retry_count;
if (previousRetryCount == null) {
  try { previousRetryCount = $('Build AI Planner Body').first().json._retry_count; } catch (error) {}
}
const retryCount = Number(previousRetryCount || 0) + 1;

if (retryCount > 2) {
    const ctx = $('Build Daily Context').first().json;
  const failurePayload = { mpId: ctx.mpId || '', planId: ctx.planClaim?.plan_id || '', runSlot: ctx.runSlot, stage: 'planner', errors: input.errors || [], retryCount };
  throw new Error('Content generation failed after ' + retryCount + ' attempts. ' + JSON.stringify(failurePayload));
}

// Pass original research data back to AI Planner for retry
const research = $('Parse Research').first().json;
return [{ json: { ...research, _retry_count: retryCount } }];

