let parsed = typeof response === 'string' ? repairJSON(response) : response;
if (parsed && typeof parsed.final_schema === 'string') parsed = repairJSON(parsed.final_schema);
else if (parsed && typeof parsed.final === 'string') parsed = repairJSON(parsed.final);
const validTemplates = new Set(['tips-content', 'code-content', 'visual-content', 'template1-content', 'insight-content', 'editorial-content', 'momentum-content']);
parsed.mpId = normalizeMpId(parsed.mpId || upstreamMpId);
