if (!validTemplates.has(parsed.template)) throw new Error('Parse Brief: invalid or missing template: ' + parsed.template);
if (!Array.isArray(parsed.researchTopics) || parsed.researchTopics.length === 0) throw new Error('Parse Brief: missing or empty researchTopics array');
if (parsed.imagePlan && parsed.imagePlan.introLogoSlots) {
  delete parsed.imagePlan.introLogoSlots;
}
if (parsed.imagePlan && typeof parsed.imagePlan === 'object' && Object.keys(parsed.imagePlan).length === 0) {
  parsed.imagePlan = {};
}
const dir = '/home/node/ig-templates-demo/content-plans/brief-plans';
const outPath = dir + '/' + parsed.mpId + '-brief.json';
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(outPath, JSON.stringify(parsed, null, 2), 'utf8');
const ctx = $('Build Daily Context').first().json;
return [{ json: { 
