function slugify(value) {
  return String(value || 'general').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+/g, '-').replace(/^-+|-+$/g, '') || 'general';
}
function shortHash(value) {
  let hash = 0;
  for (let i = 0; i < value.length; i++) hash = (hash * 31 + value.charCodeAt(i)) >>> 0;
  return hash.toString(36).slice(0, 8);
}
function shortenMpId(value, maxLength = 96) {
  if (value.length <= maxLength) return value;
  const hash = shortHash(value);
  const head = value.slice(0, maxLength - hash.length - 1).replace(/-+$/g, '');
  return `${head}-${hash}`;
}
function buildMpId(date, topic) {
  const yyyymmdd = String(date || new Date().toISOString().slice(0, 10)).replace(/[^0-9]/g, '').slice(0, 8) || new Date().toISOString().slice(0, 10).replace(/-/g, '');
  return shortenMpId(`mp-${yyyymmdd}-${slugify(topic)}`);
}
function normalizeMpId(mpId, fallbackDate) {
  if (!mpId) return buildMpId(fallbackDate, 'general');
  const sanitized = String(mpId).toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/-+/g, '-').replace(/^-+|-+$/g, '');
  const ensuredPrefix = sanitized.startsWith('mp-') ? sanitized : `mp-${sanitized || 'general'}`;
  return shortenMpId(ensuredPrefix);
}

