    aiCaption = parsed.instagram_caption || parsed.caption || null;
    if (aiCaption && aiCaption.length > 1200) aiCaption = aiCaption.substring(0, 1200);
  }
} catch(e) {
  captionError = e.message;
}

const finalCaption = aiCaption || instagram_caption;
const finalHashtags = hashtags;

if (aiCaption) {
  try {
    const mpId = plan.mpId || 'unknown';
    const dir = '/home/node/ig-templates-demo/content-plans/captions';
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(dir + '/' + mpId + '-caption.json', JSON.stringify({
      mpId: mpId,
      caption: finalCaption,
      hashtags: finalHashtags,
      source: 'ai',
      originalPlannerCaption: instagram_caption
    }, null, 2), 'utf8');
  } catch(e) {}
}

return [{ json: {
  ...inputData,
  ...plan,
  instagram_caption: finalCaption,
  hashtags: finalHashtags,
  hashtagsStr: finalHashtags.join(' '),
  _captionSource: aiCaption ? 'ai' : 'planner_fallback',
